import { useState } from 'react';
import { JxButton, JxCalendar } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date) => void;
}

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function daysAgo(days: number): Date {
  const result = startOfDay(new Date());
  result.setDate(result.getDate() - days);
  return result;
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [value, setValue] = useState<Date>(() => startOfDay(new Date()));

  const handleChange = (date: Date) => {
    const normalized = startOfDay(date);
    setValue(normalized);
    onChange?.(normalized);
  };

  const quickOptions = [
    { label: 'Сегодня', getDate: () => daysAgo(0) },
    { label: 'Вчера', getDate: () => daysAgo(1) },
    { label: 'Неделя назад', getDate: () => daysAgo(7) },
  ];

  return (
    <div className="jx-stack jx-stack-gap-md">
      <div className="jx-inline jx-inline-gap-sm">
        {quickOptions.map((option) => (
          <JxButton
            key={option.label}
            variant="secondary"
            size="sm"
            onClick={() => handleChange(option.getDate())}
          >
            {option.label}
          </JxButton>
        ))}
      </div>
      <JxCalendar value={value} onValueChange={handleChange} />
    </div>
  );
}

